<script type="text/javascript">
jQuery(document).ready(function()
{
    jQuery('#searching').on( "click", function(event)
    {
        event.preventDefault();
            const form = jQuery('#formBodySearch');
            javascript:jQuery.LoadingStructData();   
            jQuery.ajax({
                type: 'POST',          
                url: '<?php echo url_for('com_enviada/resultado');?>',         
                data: form.serialize(), //serializar.
                success: function(response)
                {
                    if(response.status == 403)
                    {
                        javascript:jQuery.CloseLoadingStructData();
                        toastr.warning(response.mensaje);  
                    }
                    else
                    {
                        jQuery('#<?php echo md5('strlistinfo');?>').html(response);
                        javascript:jQuery.CloseLoadingStructData();
                        toastr.success("consulta exitosa!!!");
                    }   
                },
                error: function(jqXHR, textStatus, errorThrown) 
                {
                    if (jqXHR.status == 404) 
                    {
                        javascript:jQuery.CloseLoadingStructData();  
                        toastr.error("Debe resolver primero el CAPTCHA!!");
                    }
                    else if(jqXHR.status == 400)
                    {
                        javascript:jQuery.CloseLoadingStructData();  
                        toastr.error("Debe ingresar el numero de Radicado!!");
                    } 
                    else 
                    {
                        javascript:jQuery.CloseLoadingStructData();  
                        //toastr.error("Error Interno del Servidor!");
                    }
                }
            });
	});
});
</script>


<script type="text/javascript">

function regresar_valor(id, titulo, subserie, destino, descripcion_destino) 
  {

    if (jQuery('#unidaddocumental_id').length)
    {
        jQuery('#unidaddocumental_id').val(id);
    }
    
    if (jQuery('#nombre').length)
    {
        jQuery('#nombre').val(titulo);
    }

    if (jQuery('#destinotransferencia_id').length)
    {
        jQuery('#destinotransferencia_id').val(destino);
    }

    if (jQuery('#descripcion_destino').length)
    {
        jQuery('#descripcion_destino').val(descripcion_destino);
    }

    if (jQuery('#subserie_id').length)
    {
        jQuery('#subserie_id').val(subserie);
    }

    parent.jQuery.CloseModalSIMAD();
  }

  function regresar_valor2(id, titulo, subserie, destino, descripcion_destino) 
  {
    $closeModal = false;
    if (jQuery('#unidaddocumental_id').length)
    {
        jQuery('#unidaddocumental_id').val(id);
    }
    else if (jQuery(window.parent.document).find('#unidaddocumental_id').length)
    {
        jQuery(window.parent.document).find('#unidaddocumental_id').val(id);
        $closeModal = true;
    }
    
    if (jQuery('#nombre').length)
    {
        jQuery('#nombre').val(titulo);
    } else if (jQuery(window.parent.document).find('#nombre').length){
        jQuery(window.parent.document).find('#nombre').val(titulo);
    }

    if (jQuery('#destinotransferencia_id').length)
    {
        jQuery('#destinotransferencia_id').val(destino);
    }else if (jQuery(window.parent.document).find('#destinotransferencia_id').length){
        jQuery(window.parent.document).find('#destinotransferencia_id').val(destino);
    }

    if (jQuery('#descripcion_destino').length)
    {
        jQuery('#descripcion_destino').val(descripcion_destino);
    }else if (jQuery(window.parent.document).find('#descripcion_destino').length)
    {
        jQuery(window.parent.document).find('#descripcion_destino').val(descripcion_destino);
    }

    if (jQuery('#subserie_id').length)
    {
        jQuery('#subserie_id').val(subserie);
    }else if (jQuery(window.parent.document).find('#subserie_id').length){
        jQuery(window.parent.document).find('#subserie_id').val(subserie);
    }

    if($closeModal === true) { parent.jQuery.CloseModalSIMAD(); }
  }  


</script>